{{ config(materialized='table', partition_by={'field':'transaction_date','data_type':'date'}, cluster_by=['customer_id','account_id','transaction_type_id']) }}
select t.transaction_id,c.customer_sk,a.account_sk,t.customer_id,t.account_id,t.account_type_id,t.branch_id,t.transaction_type_id,cast(format_date('%Y%m%d',t.transaction_date) as int64) date_sk,t.transaction_ts,t.transaction_date,t.amount,t.currency,t.channel,t.merchant_category,t.reference,t.is_currency_mismatch,t.is_high_value,t.is_structuring_candidate,t.is_dormant_reactivation_burst,t.batch_id,t.source_file from {{ ref('slv_transactions') }} t join {{ ref('dim_account') }} a on a.account_id=t.account_id and t.transaction_ts between a.effective_from and a.effective_to join {{ ref('dim_customer') }} c on c.customer_id=a.customer_id and t.transaction_ts between c.effective_from and c.effective_to where t.is_valid_record
